// 1. Internal Rate Limit Check (Gateway -> Rate Limiter Service / Redis)
POST /internal/v1/rate-limit/check
Request:
{
  "subject_key": "usr_94812",
  "route_id": "POST:/api/v1/orders",
  "cost": 1
}
Response (200 OK — Allowed / 429 Too Many Requests — Throttled):
{
  "allowed": false,
  "limit": 100,
  "remaining": 0,
  "reset_epoch_seconds": 1790784060,
  "retry_after_ms": 1250
}

// 2. Client-Facing HTTP 429 Response
HTTP/1.1 429 Too Many Requests
X-RateLimit-Limit: 100
X-RateLimit-Remaining: 0
X-RateLimit-Reset: 1790784060
Retry-After: 2
{
  "error": "rate_limit_exceeded",
  "message": "Quota of 100 requests/min exceeded. Retry after 2 seconds."
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY rate_limit_policies (PostgreSQL (Config DB)) {
  [PK ] policy_id              VARCHAR(64)
  [IDX] route_pattern          VARCHAR(128)
        algorithm              ENUM('TOKEN','SLIDING')
        bucket_capacity        INT
        refill_rate_per_sec    INT
}

ENTITY client_tier_bindings (PostgreSQL + L1 Cache) {
  [PK ] client_id              VARCHAR(64)
  [FK ] policy_id              VARCHAR(64)
        tier_name              VARCHAR(32)
        override_multiplier    DECIMAL(4,2)
        updated_at             TIMESTAMPTZ
}

ENTITY token_bucket_state (Redis Cluster (In-Memory)) {
  [PK ] bucket_key             STRING (rl:{id}:{route})
        tokens                 FLOAT
        last_refill_ms         INT64
  [IDX] ttl_seconds            INT (EXPIRE 3600)
}

// Relationships: rate_limit_policies --(1 : N (applies to))--> client_tier_bindings --(1 : N (tracks runtime state))--> token_bucket_state

/*
 * ==================== FLOW 1: ATOMIC REDIS LUA TOKEN BUCKET =========================
 *
 * Gateway Pod -> EVALSHA <script_sha> 1 "rl:api:user_42" <capacity> <refill_rate> <now_ms> <cost>
 *   |
 *   +--> [Inside Redis Shard - Single Threaded Atomic Execution]
 *        1. HMGET key "tokens" "last_refill_ms"
 *        2. delta_sec = max(0, now_ms - last_refill_ms) / 1000.0
 *        3. current_tokens = min(capacity, old_tokens + (delta_sec * refill_rate))
 *        4. if current_tokens >= cost:
 *              current_tokens -= cost
 *              HMSET key "tokens" current_tokens "last_refill_ms" now_ms
 *              PEXPIRE key ttl_ms
 *              return {1, current_tokens, 0}
 *           else:
 *              retry_ms = ((cost - current_tokens) / refill_rate) * 1000
 *              return {0, current_tokens, retry_ms}
 *
 * ==================== FLOW 2: GATEWAY EXECUTION & CIRCUIT BREAKER ====================
 *
 * Request -> Extract Key -> Match Rule -> Try Redis EVALSHA (Timeout = 5ms)
 *                                            |-- Success -> Set X-RateLimit Headers -> 200 or 429
 *                                            +-- Timeout/Error -> Fallback Local Memory Bucket
 */

package com.sdi.ratelimiter.service;

import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class DistributedTokenBucketLimiter {

    // Atomic Lua Script: executes Token Bucket refill + consume in 1 round-trip
    private static final String TOKEN_BUCKET_LUA = """
            local key = KEYS[1]
            local capacity = tonumber(ARGV[1])
            local refill_rate = tonumber(ARGV[2])
            local now_ms = tonumber(ARGV[3])
            local requested = tonumber(ARGV[4])

            local data = redis.call('HMGET', key, 'tokens', 'last_refill_ms')
            local tokens = tonumber(data[1])
            local last_refill = tonumber(data[2])

            if tokens == nil then
                tokens = capacity
                last_refill = now_ms
            else
                local elapsed_sec = math.max(0, now_ms - last_refill) / 1000.0
                tokens = math.min(capacity, tokens + (elapsed_sec * refill_rate))
                last_refill = now_ms
            end

            local allowed = 0
            local retry_after_ms = 0

            if tokens >= requested then
                tokens = tokens - requested
                allowed = 1
                redis.call('HMSET', key, 'tokens', tokens, 'last_refill_ms', last_refill)
                local ttl_ms = math.ceil((capacity / refill_rate) * 2000)
                redis.call('PEXPIRE', key, ttl_ms)
            else
                retry_after_ms = math.ceil(((requested - tokens) / refill_rate) * 1000)
            end

            return { allowed, math.floor(tokens), retry_after_ms }
            """;

    private final StringRedisTemplate redisTemplate;
    private final DefaultRedisScript<List> redisScript;
    // Fallback local state if Redis cluster is unreachable
    private final ConcurrentHashMap<String, LocalBucket> fallbackBuckets = new ConcurrentHashMap<>();

    public DistributedTokenBucketLimiter(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
        this.redisScript = new DefaultRedisScript<>(TOKEN_BUCKET_LUA, List.class);
    }

    @SuppressWarnings("unchecked")
    public RateLimitDecision evaluate(RateLimitRule rule, String subjectKey, int cost) {
        String redisKey = "rl:{" + rule.ruleId() + ":" + subjectKey + "}";
        long nowMs = Instant.now().toEpochMilli();

        try {
            List<Long> result = (List<Long>) redisTemplate.execute(
                    redisScript,
                    Collections.singletonList(redisKey),
                    String.valueOf(rule.bucketCapacity()),
                    String.valueOf(rule.refillRatePerSec()),
                    String.valueOf(nowMs),
                    String.valueOf(cost)
            );

            boolean allowed = result.get(0) == 1L;
            long remaining = result.get(1);
            long retryAfterMs = result.get(2);

            return new RateLimitDecision(
                    allowed, rule.ruleId(), rule.bucketCapacity(), remaining, retryAfterMs
            );
        } catch (Exception redisFailure) {
            // Graceful degradation: fall back to local in-memory bucket (or fail-open)
            return evaluateLocalFallback(rule, redisKey, cost, nowMs);
        }
    }

    private RateLimitDecision evaluateLocalFallback(
            RateLimitRule rule, String key, int cost, long nowMs) {
        LocalBucket bucket = fallbackBuckets.computeIfAbsent(
                key, k -> new LocalBucket(rule.bucketCapacity(), nowMs));
        return bucket.tryConsume(rule, cost, nowMs);
    }

    private static final class LocalBucket {
        private double tokens;
        private long lastRefillMs;

        LocalBucket(double tokens, long lastRefillMs) {
            this.tokens = tokens;
            this.lastRefillMs = lastRefillMs;
        }

        synchronized RateLimitDecision tryConsume(RateLimitRule rule, int cost, long nowMs) {
            double elapsedSec = Math.max(0, nowMs - lastRefillMs) / 1000.0;
            tokens = Math.min(rule.bucketCapacity(), tokens + elapsedSec * rule.refillRatePerSec());
            lastRefillMs = nowMs;
            if (tokens >= cost) {
                tokens -= cost;
                return new RateLimitDecision(true, rule.ruleId(), rule.bucketCapacity(), (long) tokens, 0);
            }
            long retryMs = (long) (((cost - tokens) / rule.refillRatePerSec()) * 1000);
            return new RateLimitDecision(false, rule.ruleId(), rule.bucketCapacity(), (long) tokens, retryMs);
        }
    }
}
